namespace AjivaGenerator.Shared;

/// <summary>
/// Helper class for generating network packet serialization code
/// Can be reused by both NetworkPacketsSourceGenerator and EcsSourceGenerator
/// </summary>
public static class NetworkPacketGenerationHelper
{
    private static readonly Dictionary<string, string> KnownTypeLookup = new()
    {
        { "bool", "Bool" },
        { "byte", "Byte" },
        { "sbyte", "SByte" },
        { "short", "Short" },
        { "ushort", "UShort" },
        { "int", "Int" },
        { "uint", "UInt" },
        { "long", "Long" },
        { "ulong", "ULong" },
        { "float", "Float" },
        { "double", "Double" },
        { "string", "String" },
        { "u64", "ULong" },
        { "u32", "UInt" },
        { "u16", "UShort" },
        { "i64", "Long" },
        { "i32", "Int" },
        { "i16", "Short" },
        { "u8", "Byte" },
        { "i8", "SByte" },
        { "f32", "Float" },
        { "f64", "Double" },
        { "Quaternion", "Quaternion" },
        { "Vector3", "Vector3" },
    };

    private static readonly Dictionary<string?, TypeGenerationInfo?> TypeGenerationInfoCache = [];

    public record TypeGenerationInfo(
        string TypeName,
        string GetMethod,
        string AddMethod,
        bool IsPrimitive,
        bool IsMessageSerializable);

    /// <summary>
    /// Gets type generation information for network serialization
    /// </summary>
    public static TypeGenerationInfo? GetTypeGenerationInfo(SemanticModel semanticModel, TypeSyntax typeSyntax)
    {
        var key = typeSyntax.ToFullString();
        if (TypeGenerationInfoCache.TryGetValue(key, out var info)) return info;
        
        var typeSymbol = semanticModel.GetTypeInfo(typeSyntax).Type;
        if (typeSymbol is null) return null;
        
        var typeName = typeSyntax.ToString();

        TypeGenerationInfo? res = null;
        
        // Check for known primitive types
        if (KnownTypeLookup.ContainsKey(typeName))
        {
            res = new TypeGenerationInfo(typeName, "Get" + KnownTypeLookup[typeName],
                "Add" + KnownTypeLookup[typeName], true, false);
        }

        // Check for IMessageSerializable types
        if (typeSymbol.Interfaces.Any(i => i.ToDisplayString() == "Riptide.IMessageSerializable"))
        {
            res = new TypeGenerationInfo(typeName, "GetSerializable<" + typeName + ">",
                "AddSerializable<" + typeName + ">", false, true);
        }

        if (res is null) return null;

        TypeGenerationInfoCache[key] = res;
        return res;
    }

    /// <summary>
    /// Generates serialization method body for a list of fields
    /// </summary>
    public static SyntaxList<StatementSyntax> GenerateSerializationStatements(
        IEnumerable<(TypeSyntax Type, string fieldName)> fields)
    {
        var statements = new SyntaxList<StatementSyntax>();

        foreach (var member in fields)
        {
            // call message.Add({fieldName})
            statements = statements.Add(
                ExpressionStatement(
                    InvocationExpression(
                        MemberAccessExpression(
                            SyntaxKind.SimpleMemberAccessExpression,
                            IdentifierName("message"),
                            IdentifierName("Add")
                        )
                    ).WithArgumentList(
                        ArgumentList(
                            SingletonSeparatedList(
                                Argument(IdentifierName(member.fieldName))
                            )
                        )
                    )
                )
            );
        }

        return statements;
    }

    /// <summary>
    /// Generates deserialization method body for a list of fields
    /// </summary>
    public static SyntaxList<StatementSyntax> GenerateDeserializationStatements(
        IEnumerable<(TypeSyntax Type, string fieldName)> fields)
    {
        var statements = new SyntaxList<StatementSyntax>();

        foreach (var member in fields)
        {
            // call message.Get(out {fieldName})
            statements = statements.Add(
                ExpressionStatement(
                    InvocationExpression(
                        MemberAccessExpression(
                            SyntaxKind.SimpleMemberAccessExpression,
                            IdentifierName("message"),
                            IdentifierName("Get")
                        )
                    ).WithArgumentList(
                        ArgumentList(
                            SingletonSeparatedList(
                                Argument(
                                    MemberAccessExpression(
                                        SyntaxKind.SimpleMemberAccessExpression,
                                        IdentifierName("this"),
                                        IdentifierName(member.fieldName)
                                    )
                                ).WithRefOrOutKeyword(Token(SyntaxKind.OutKeyword))
                            )
                        )
                    )
                )
            );
        }

        return statements;
    }

    /// <summary>
    /// Generates ToMessage method with packet type header
    /// </summary>
    public static MethodDeclarationSyntax GenerateToMessageMethod(
        string className,
        IEnumerable<(TypeSyntax Type, string fieldName)> fields,
        SourceProductionContext context,
        SemanticModel semanticModel)
    {
        List<StatementSyntax> toMessageBody =
        [
            // var msg = Message.Create(sendMode);
            LocalDeclarationStatement(
                VariableDeclaration(IdentifierName("var"))
                    .WithVariables(SingletonSeparatedList(
                        VariableDeclarator(Identifier("msg"))
                            .WithInitializer(EqualsValueClause(
                                InvocationExpression(MemberAccessExpression(
                                    SyntaxKind.SimpleMemberAccessExpression,
                                    IdentifierName("global::Riptide.Message"),
                                    IdentifierName("Create"))
                                ).WithArgumentList(ArgumentList(SingletonSeparatedList(
                                    Argument(IdentifierName("sendMode")))))
                            )))
                    )),
            
            // msg.AddUShort((ushort)PacketType.{className});
            ExpressionStatement(InvocationExpression(
                    MemberAccessExpression(
                        SyntaxKind.SimpleMemberAccessExpression,
                        IdentifierName("msg"),
                        IdentifierName("AddUShort")
                    )).WithArgumentList(ArgumentList(SingletonSeparatedList(
                    Argument(CastExpression(
                        PredefinedType(Token(SyntaxKind.UShortKeyword)),
                        IdentifierName("PacketType." + className)
                    ))
                )))
            )
        ];

        // Add serialization calls for each field
        foreach (var f in fields)
        {
            toMessageBody.Add(ExpressionStatement(InvocationExpression(
                    MemberAccessExpression(
                        SyntaxKind.SimpleMemberAccessExpression,
                        IdentifierName("msg"),
                        IdentifierName(GetTypeAddMethod(context, semanticModel, f.Type))
                    )).WithArgumentList(ArgumentList(SingletonSeparatedList(
                    Argument(IdentifierName(f.fieldName))
                )))
            ));
        }

        toMessageBody.Add(ReturnStatement(IdentifierName("msg")));

        return MethodDeclaration(IdentifierName("global::Riptide.Message"), "ToMessage")
            .AddModifiers(Token(SyntaxKind.PublicKeyword))
            .AddParameterListParameters(
                Parameter(Identifier("sendMode"))
                    .WithType(IdentifierName("global::Riptide.MessageSendMode"))
            )
            .WithBody(Block(toMessageBody));
    }

    /// <summary>
    /// Generates FromMessage static method
    /// </summary>
    public static MethodDeclarationSyntax GenerateFromMessageMethod(
        string className,
        IEnumerable<(TypeSyntax Type, string fieldName)> fields,
        SourceProductionContext context,
        SemanticModel semanticModel)
    {
        return MethodDeclaration(IdentifierName(className), "FromMessage")
            .AddModifiers(Token(SyntaxKind.PublicKeyword), Token(SyntaxKind.StaticKeyword))
            .AddParameterListParameters(Parameter(Identifier("message"))
                .WithType(IdentifierName("global::Riptide.Message")))
            .WithBody(Block(
                ReturnStatement(
                    ObjectCreationExpression(IdentifierName(className))
                        .WithArgumentList(
                            ArgumentList(
                                SeparatedList(
                                    fields.Select(f => Argument(
                                        InvocationExpression(
                                            MemberAccessExpression(
                                                SyntaxKind.SimpleMemberAccessExpression,
                                                IdentifierName("message"),
                                                IdentifierName(GetTypeGetMethod(context, semanticModel, f.Type))
                                            ))
                                    ))
                                )
                            )
                        )
                )
            ));
    }

    /// <summary>
    /// Generates Send method for sending to a single connection
    /// </summary>
    public static MethodDeclarationSyntax GenerateSendMethod()
    {
        return MethodDeclaration(PredefinedType(Token(SyntaxKind.VoidKeyword)), "Send")
            .AddModifiers(Token(SyntaxKind.PublicKeyword))
            .AddParameterListParameters(
                Parameter(Identifier("connection"))
                    .WithType(IdentifierName("global::Riptide.Connection")),
                Parameter(Identifier("sendMode"))
                    .WithType(IdentifierName("global::Riptide.MessageSendMode"))
            )
            .WithBody(Block(ExpressionStatement(InvocationExpression(
                    MemberAccessExpression(
                        SyntaxKind.SimpleMemberAccessExpression,
                        IdentifierName("connection"),
                        IdentifierName("Send")
                    ))
                .WithArgumentList(ArgumentList(SingletonSeparatedList(
                    Argument(InvocationExpression(MemberAccessExpression(
                            SyntaxKind.SimpleMemberAccessExpression,
                            ThisExpression(),
                            IdentifierName("ToMessage")
                        ))
                        .WithArgumentList(ArgumentList(
                            SingletonSeparatedList(
                                Argument(IdentifierName("sendMode"))
                            ))
                        ))
                ))))
            ));
    }

    /// <summary>
    /// Generates SendToAll method for broadcasting to all connections
    /// </summary>
    public static MethodDeclarationSyntax GenerateSendToAllMethod()
    {
        return MethodDeclaration(PredefinedType(Token(SyntaxKind.VoidKeyword)), "SendToAll")
            .AddModifiers(Token(SyntaxKind.PublicKeyword))
            .AddParameterListParameters(
                Parameter(Identifier("server"))
                    .WithType(IdentifierName("global::Riptide.Server")),
                Parameter(Identifier("sendMode"))
                    .WithType(IdentifierName("global::Riptide.MessageSendMode"))
            )
            .WithBody(Block(ExpressionStatement(InvocationExpression(
                    MemberAccessExpression(
                        SyntaxKind.SimpleMemberAccessExpression,
                        IdentifierName("server"),
                        IdentifierName("SendToAll")
                    ))
                .WithArgumentList(ArgumentList(SingletonSeparatedList(
                    Argument(InvocationExpression(MemberAccessExpression(
                            SyntaxKind.SimpleMemberAccessExpression,
                            ThisExpression(),
                            IdentifierName("ToMessage")
                        ))
                        .WithArgumentList(ArgumentList(
                            SingletonSeparatedList(
                                Argument(IdentifierName("sendMode"))
                            ))
                        ))
                ))))
            ));
    }

    /// <summary>
    /// Gets the appropriate Add method name for a type
    /// </summary>
    public static string GetTypeAddMethod(SourceProductionContext context, SemanticModel semanticModel, TypeSyntax type)
    {
        if (GetTypeGenerationInfo(semanticModel, type) is { } genTypeInfo) 
            return genTypeInfo.AddMethod;

        context.ReportDiagnostic(Diagnostic.Create(NetworkGeneratorRules.UnknownTypeRule, type.GetLocation(),
            type.ToFullString()));
        return "ERROR";
    }

    /// <summary>
    /// Gets the appropriate Get method name for a type
    /// </summary>
    public static string GetTypeGetMethod(SourceProductionContext context, SemanticModel semanticModel, TypeSyntax type)
    {
        if (GetTypeGenerationInfo(semanticModel, type) is { } genTypeInfo) 
            return genTypeInfo.GetMethod;

        context.ReportDiagnostic(Diagnostic.Create(NetworkGeneratorRules.UnknownTypeRule, type.GetLocation(),
            type.ToFullString()));
        return "ERROR";
    }

    /// <summary>
    /// Converts text to PascalCase
    /// </summary>
    public static string ToPascalCase(string text) => text[..1].ToUpper() + text[1..];

    /// <summary>
    /// Converts text to camelCase
    /// </summary>
    public static string ToCamelCase(string text) => text[..1].ToLower() + text[1..];
}
